import { Component, inject } from '@angular/core';
import { TablaComponent, TableDefinition } from "../../shared/tabla/tabla.component";
import { BuscadorCreditosComponent } from "../../main/estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { LiquidacionAnticipadaService } from '../../controllers/liquidacion.anticipada.service';
import { Conditional } from '../../controllers/super.service';

const TABLE_DEF: TableDefinition = {
  emptyMsg:'No hay liquidaciones anticipadas registradas.',
  columns: [
    'credito_id',
    'fecha',
    {
      key: 'iva_condonado',
      header: 'Iva Condonado',
      pipe: 'currency'
    },
    {
      key: 'interes_condonado',
      header: 'Iva Condonado',
      pipe: 'currency'
    },
    {
      key: 'capital_adelantado',
      header: 'Capital Adelantado',
      pipe: 'currency'
    },
    'comentarios',
    {
      key: 'usuarios',
      subKey: 'nombre',
      header: 'Creado Por:'
    }
  ]
}

@Component({
  selector: 'app-liquidacion-anticipada-tabla',
  imports: [
    TablaComponent,
    BuscadorCreditosComponent
  ],
  templateUrl: './liquidacion-anticipada-tabla.component.html',
  styleUrl: './liquidacion-anticipada-tabla.component.css'
})
export class LiquidacionAnticipadaTablaComponent {
  tabla = TABLE_DEF
  conditionals: Conditional[] = [
    {
      key: 'deleted_at',
      operator: 'IS NULL',
      value: null,
    }
  ]
  public credito_id?: number
  public liquidacionAnticipadaController = inject(LiquidacionAnticipadaService)

  public aplicarFiltros() {
    if (this.credito_id) {
      this.conditionals = [
        {
          key: 'deleted_at',
          operator: 'IS NULL',
          value: null,
        },
        {
          key: 'credito_id',
          operator: '=',
          value: this.credito_id
        }
      ]
    } else {
      this.conditionals = [
        {
          key: 'deleted_at',
          operator: 'IS NULL',
          value: null,
        }
      ]
    }
  }
}
