import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ToastyService } from '../../services/toasty.service';
import { Toasty } from '../../models/toasty.model';
import { ToastyNotificationComponent } from '../../toasty-notification.component';

@Component({
    selector: 'app-toasty-container',
    imports: [CommonModule, ToastyNotificationComponent],
    templateUrl: './toasty-container.component.html',
    styleUrls: ['./toasty-container.component.css']
})
export class ToastyContainerComponent {
  constructor(public toastyService: ToastyService) {}

  removeToast(id: number) {
    this.toastyService.remove(id);
  }
}
