import { Injectable } from '@angular/core';
import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';

import { CreditoAbonoService } from '../../../controllers/credito.abono.service';
import { CreditoAbono } from '../../../models/credito.abono';
import { PolizaInfo, PolizaItemsCreditos, PolizaItemsIngresos, PolizaItemsInteres, PolizaMov } from '../../../models/poliza.items';
import { Credito } from '../../../models/credito.model';
import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { SesionService } from '../../../controllers/sesion.service';
import { CreditoService } from '../../../controllers/credito.service';

@Injectable({
  providedIn: 'root'
})
export class PolizaHelperService {

  EXCEL_PLANTILLA = 'assets/plantillas_excel/polizas_interes.xls';

  constructor(
    // private excelService: GeneradorExcelService,
    private creditoAbonoController: CreditoAbonoService,
    private comisionesController: CreditoService, // TablaComisionService,
    private utilsEdoCta: UtilsEstadoCuentaService,
    // private facturaMasiva: FacturaMasivaService,
    private sesionService: SesionService,
  ) { }

  async generarPolizaInteres(poliza: PolizaInfo, data: PolizaItemsInteres[]) {

    const destWorkbook: XLSX.WorkBook = XLSX.utils.book_new();

    const response = await fetch(this.EXCEL_PLANTILLA);
    const arrayBuffer = await response.arrayBuffer();

    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    const sheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[sheetName]; // INFO: nota se tiene que acceder con el nombre de la hoja

    // -- Generar la Info de la Póliza
    this.setPolizaInfo(worksheet, 23, poliza);

    let totalPoliza = 0;
    let totalIva = 0;
    let currentRow = 0;
    const startRow = 24; // INFO: según la fila de Contpaq + 1
    let maxRow = startRow;
    data.forEach((row, index) => {
      currentRow = startRow + index;

      let movimiento: PolizaMov = {
        cuenta_contable: '227143005',
        tipo_mov: 0, // 0 para cargo
        cantidad: row.factura?.monto_factura || 0,
        concepto: 'INTERES',
        uuid: row.factura?.uid_cicofi || '',
        fecha: row.abono.fecha.split('T')[0].replace(/-/g, ''),
      }
      this.setMovimientoPoliza(worksheet, currentRow, movimiento);

      maxRow = currentRow; // Actualizar la fila máxima

      if (row.factura) {
        // console.info(typeof row.factura.monto_factura, row.factura.monto_factura);
        let montoFactura = parseFloat(typeof row.factura.monto_factura === 'string' ? `${row.factura.monto_factura}` : '0');
        const iva = this.calcularIva(montoFactura);
        totalIva += iva;
        totalPoliza += montoFactura;
      }
    });

    // -- Total de interés
    currentRow += 1; // Incrementar para la siguiente fila

    let movInteres: PolizaMov = {
      cuenta_contable: '420100000',
      tipo_mov: 1, // 1 para abono
      cantidad: totalPoliza,
      concepto: 'TOTAL',
      uuid: '',
      fecha: '',
    }
    this.setMovimientoPoliza(worksheet, currentRow, movInteres);
    // maxRow = currentRow; // Actualizar la fila máxima

    // -- Movimiento cargo de IVA
    currentRow += 1;
    let movIva: PolizaMov = {
      cuenta_contable: '215011000',
      tipo_mov: 0, // 0 para cargo
      cantidad: totalIva,
      concepto: 'IVA INTERES',
      uuid: '',
      fecha: '',
    }
    this.setMovimientoPoliza(worksheet, currentRow, movIva);

    // Movimiento de abono de IVA
    currentRow += 1; // Incrementar para la siguiente fila
    movIva.tipo_mov = 1;
    this.setMovimientoPoliza(worksheet, currentRow, movIva);

    maxRow = currentRow; // Actualizar la fila máxima

    if (worksheet['!ref']) {
      const range = XLSX.utils.decode_range(worksheet['!ref']);
      // range.e.r = startRow + data.length - 1; // Ajustar el rango para incluir las nuevas filas
      range.e.r = startRow + maxRow; // Ajustar el rango para incluir las nuevas filas
      worksheet['!ref'] = XLSX.utils.encode_range(range);
    } else {
      worksheet['!ref'] = `A1:K${maxRow + 1}`;
    }

    // -- Guardarmos la hoja de trabajo en libro destino
    XLSX.utils.book_append_sheet(destWorkbook, worksheet, 'Poliza Interes');

    const excelBuffer: any = XLSX.write(destWorkbook, { bookType: 'xls', type: 'array' });

    const wbout: Blob = new Blob([excelBuffer], {
      // type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=UTF-8'
      type: 'application/vnd.ms-excel'
    });

    // Usar file-saver para la descarga
    saveAs(wbout, `Poliza_interes_${new Date().getTime()}.xls`);
  }

  async generarPolizaIngresos(poliza: PolizaInfo, data: PolizaItemsIngresos[]) {
    console.info(data);

    const destWorkbook: XLSX.WorkBook = XLSX.utils.book_new();

    const response = await fetch(this.EXCEL_PLANTILLA);
    const arrayBuffer = await response.arrayBuffer();

    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    const sheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[sheetName];

    this.setPolizaInfo(worksheet, 23, poliza);

    let totalPoliza = 0;
    let currentRow = 24;
    for (const dataItem of data) {

      let movimiento: PolizaMov = {
        cuenta_contable: '116144029',
        tipo_mov: 1,
        cantidad: dataItem.factura?.monto_factura || 0,
        concepto: 'COBRANZA',
        uuid: dataItem.factura?.uid_cicofi || '',
        fecha: dataItem.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '',
      }

      this.setMovimientoPoliza(worksheet, currentRow, movimiento);

      if (dataItem.factura) {
        let cantidad = parseFloat(typeof dataItem.factura.monto_factura === 'string' ? `${dataItem.factura.monto_factura}` : '0');
        totalPoliza += cantidad;
      }

      currentRow += 1;
    } // for

    // -- Movimiento de totales
    let movmientoTotal: PolizaMov = {
      cuenta_contable: '101002000',
      tipo_mov: 0,
      cantidad: totalPoliza,
      concepto: 'COBRANZA',
      uuid: '',
      fecha: '',
    }
    this.setMovimientoPoliza(worksheet, currentRow, movmientoTotal);

    currentRow += 1;

    if (worksheet['!ref']) {
      const range = XLSX.utils.decode_range(worksheet['!ref']);
      range.e.r = currentRow;
      worksheet['!ref'] = XLSX.utils.encode_range(range);
    } else {
      worksheet['!ref'] = `A1:K${currentRow + 1}`;
    }

    // -- Guardarmos la hoja de trabajo en libro destino
    XLSX.utils.book_append_sheet(destWorkbook, worksheet, 'Poliza Ingresos');

    const excelBuffer: any = XLSX.write(destWorkbook, { bookType: 'xls', type: 'array' });

    const wbout: Blob = new Blob([excelBuffer], {
      type: 'application/vnd.ms-excel'
    });

    // Usar file-saver para la descarga
    saveAs(wbout, `Poliza_ingresos_${new Date().getTime()}.xls`);
  }

  ////#region -- Procesamiento de datos para póliza de interés
  async procesarDatosPolizaInteres(fechaInicial: string, fechaFinal: string) {
    return (await this.creditoAbonoController.get([
      // -- Condiciones
      {
        key: 'fecha',
        operator: '>=',
        value: fechaInicial,
      },
      {
        key: 'fecha',
        operator: '<=',
        value: fechaFinal,
      },
      {
        key: 'facturacion_detalle',
        operator: '!=',
        value: 0
      },
    ],
      undefined,
      // -- Relaciones
      [
        'creditos',
        'creditos.estadoCuenta',
        'creditos.facturacionDetalle',
      ],
      // -- ExtraData
      {
        sort: JSON.stringify({ column: 'fecha', desc: false }),
        filtro: JSON.stringify({ facturados: true }),
      }
    )).data || [];
  }

  filtrarPagosInteres(data: CreditoAbono[]): any[] {
    let polizaItems: PolizaItemsInteres[] = [];
    if (data.length === 0) {
      return [];
    }

    for (const ca of data) {
      const { creditos } = ca;
      const fd = creditos?.facturacion_detalle?.find(fd => (fd.abono_id === ca.id && fd.status_proceso === 'Completo'));
      polizaItems.push({
        abono: ca,
        factura: fd ? fd : undefined,
      });
    }
    return polizaItems;
  }
  ////#endregion -- Procesamiento de datos para póliza de interés

  ////#region -- Procesamiento de datos de las comisiones
  async procesarDatosPolizaComision(finicial: string, ffinal: string) {
    return (await this.comisionesController.get([
      // { key: 'estado', operator: '=', value: 'ACTIVO' },
      { key: 'fecha_convenio', operator: '>=', value: finicial },
      { key: 'fecha_convenio', operator: '<=', value: ffinal },
    ], undefined, [
      'facturacionDetalle',
      // 'creditos.facturacionDetalle',
    ],
      // -- extraData
      {
        sort: JSON.stringify({ column: 'fecha_convenio', desc: true }),
        filtro: 'facturados', // JSON.stringify({ facturados: true })
      })).data || [];
  }

  filtrarFacturaComision(creditos: Credito[]): PolizaItemsIngresos[] {
    let items: PolizaItemsIngresos[] = [];
    for (const credito of creditos) {
      let factura = credito.facturacion_detalle?.find(fd => fd.tipo_factura === 'comision');
      if (factura && factura.status_proceso === 'Completo') {
        items.push({
          credito: credito,
          factura: factura,
        });
      }
    }

    return items;
  }
  ////#endregion

  // #region -- Póliza de Créditos (por sesiones ??)
  async generarPolizaCreditos(poliza: PolizaInfo, data: PolizaItemsCreditos[]) {
    console.info(poliza, data);

    const destWorkbook: XLSX.WorkBook = XLSX.utils.book_new();
    const response = await fetch(this.EXCEL_PLANTILLA);
    const arrayBuffer = await response.arrayBuffer();

    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    const sheetName = workbook.SheetNames[0];
    const worksheet = workbook.Sheets[sheetName];

    this.setPolizaInfo(worksheet, 23, poliza);

    let currentRow = 24
    for (const item of data) {
      // -- Movimiento de la Póliza Info
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '116148006',
        tipo_mov: 0, // 0 para cargo
        cantidad: item.edoCuenta?.monto_total_mas_intereses || 0,
        concepto: 'ENTREGA DE CREDITO',
        uuid: '',
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '',
      });
      currentRow += 1;

      // --  Movimiento del Capital - Comisión -- datos de la factura
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '101018000',
        tipo_mov: 1,
        cantidad: 0,
        concepto: 'BANCO [cuenta_banco] EMPRENDE',
        uuid: '', // ??
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '', // ??
      });
      currentRow += 1;

      // -- Movimiento del interés ordinario
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '22614600',
        tipo_mov: 1,
        cantidad: item.edoCuenta?.interes_ordinario || 0,
        concepto: 'Emprende 2024',
        uuid: '', // ??
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '', // ??
      })

      // -- Mov. del iva del interés ordinario
      const ivaInteres = this.calcularIva(item.edoCuenta?.interes_ordinario || 0);
      currentRow += 1;
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '215011000',
        tipo_mov: 1,
        cantidad: ivaInteres,
        concepto: 'Iva Pendiente a Trasladar',
        uuid: '', // ??
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '', // ??
      })

      // -- Mov. de la Comisión
      currentRow += 1;
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '425116000',
        tipo_mov: 1,
        cantidad: item.factura?.monto_factura || 0,
        concepto: 'Comisión de Apertura',
        uuid: item.factura?.uid_cicofi || '', // ??
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '', // ??
      })

      // -- Mov. del Iva de la Comisión
      const ivaComision = this.calcularIva(item.factura?.monto_factura || 0);
      currentRow += 1;
      this.setMovimientoPoliza(worksheet, currentRow, {
        cuenta_contable: '215010000',
        tipo_mov: 1,
        cantidad: ivaComision,
        concepto: 'Iva Trasladado',
        uuid: '', // ??
        fecha: item.credito.fecha_convenio?.split('T')[0].replace(/-/g, '') || '', // ??
      })

      currentRow += 1;

    } // -- for

    if (worksheet['!ref']) {
      const range = XLSX.utils.decode_range(worksheet['!ref']);
      range.e.r = currentRow;
      worksheet['!ref'] = XLSX.utils.encode_range(range);
    } else {
      worksheet['!ref'] = `A1:K${currentRow + 1}`;
    }

    // -- Guardarmos la hoja de trabajo en libro destino
    XLSX.utils.book_append_sheet(destWorkbook, worksheet, 'Poliza');

    const excelBuffer: any = XLSX.write(destWorkbook, { bookType: 'xls', type: 'array' });

    const wbout: Blob = new Blob([excelBuffer], {
      type: 'application/vnd.ms-excel'
    });

    // Usar file-saver para la descarga
    saveAs(wbout, `Poliza_Credito_${new Date().getTime()}.xls`);
  }

  async procesarDatosPolizaCreditos(finicial: string, ffinal: string, sesionId: string = '') {
    let conditions = this.getConditionalsPolCreditos(finicial, ffinal, sesionId);
    return (await this.comisionesController.get(
      conditions.conditions,
      undefined,
      [
        'facturacionDetalle',
        'abonos',
        'convenios.conveniosPagos',
        'creditosPagos',
        'estadoCuenta',
        'sesiones',
      ],
      conditions.filter,
    )).data || [];
  }

  filtrarFacturaCreditos(creditos: Credito[]): PolizaItemsCreditos[] {
    let items: PolizaItemsCreditos[] = [];
    console.log(creditos);
    for (let credito of creditos) {
      if (credito) {
        let factura = credito.facturacion_detalle?.find(fd => fd.tipo_factura === 'comision');
        let edoCuenta = this.utilsEdoCta.getEstadoCuenta(credito);
        items.push({
          credito: credito,
          factura: factura,
          edoCuenta: edoCuenta,
          sesion: credito.sesiones,
        });
      }
    } // -- for

    return items;
  }
  // #endregion

  public async getListadoSesiones() {
    return (await this.sesionService.get([
      { key: 'fecha', operator: '!=', value: 'null' },
    ],
      undefined,
      [],
      {
        sort: JSON.stringify({ column: 'fecha', desc: true }),
      }
    )).data || [];
  }

  private getConditionalsPolCreditos(finicial: string, ffinal: string, sessionId: string): { conditions: any[], filter: any } {
    let conditions: any[] = [];
    let filter: any = {};
    if (sessionId === '') {
      conditions.push({ key: 'fecha_convenio', operator: '>=', value: finicial });
      conditions.push({ key: 'fecha_convenio', operator: '<=', value: ffinal });
      filter = {
        sort: JSON.stringify({ column: 'fecha_convenio', desc: true }),
        filtro: '',
      }
    } else {
      conditions.push({ key: 'sesion_id', operator: '=', value: sessionId });
    }

    return { conditions, filter };
  }

  private setPolizaInfo(worksheet: XLSX.WorkSheet, currentRow: number, poliza: PolizaInfo) {
    worksheet[`A${currentRow}`] = { t: 's', v: 'P' };
    worksheet[`B${currentRow}`] = { t: 's', v: poliza.fecha };
    worksheet[`C${currentRow}`] = { t: 's', v: `${poliza.tipoPol}` };
    worksheet[`D${currentRow}`] = { t: 'n', v: poliza.folio };
    worksheet[`E${currentRow}`] = { t: 'n', v: 1 };
    worksheet[`F${currentRow}`] = { t: 's', v: '1' }; // idDiario
    worksheet[`G${currentRow}`] = { t: 's', v: poliza.concepto };
    worksheet[`H${currentRow}`] = { t: 'n', v: 11 };
    worksheet[`I${currentRow}`] = { t: 's', v: '0' };
    worksheet[`J${currentRow}`] = { t: 's', v: '0' };
    worksheet[`K${currentRow}`] = { t: 's', v: poliza.guid };
  }

  private setMovimientoPoliza(worksheet: XLSX.WorkSheet, currentRow: number, movimiento: PolizaMov) {
    worksheet[`A${currentRow}`] = { t: 's', v: 'M1' };
    worksheet[`B${currentRow}`] = { t: 's', v: movimiento.cuenta_contable };
    worksheet[`C${currentRow}`] = { t: 's', v: '' };
    worksheet[`D${currentRow}`] = { t: 'n', v: movimiento.tipo_mov }; // tipo de movimiento
    worksheet[`E${currentRow}`] = { t: 'n', v: movimiento.cantidad }; // suma total del interés
    worksheet[`F${currentRow}`] = { t: 'n', v: 0 };
    worksheet[`G${currentRow}`] = { t: 'n', v: 0 };
    worksheet[`H${currentRow}`] = { t: 's', v: movimiento.concepto };
    worksheet[`I${currentRow}`] = { t: 's', v: '' };
    worksheet[`J${currentRow}`] = { t: 's', v: movimiento.uuid };
    worksheet[`K${currentRow}`] = { t: 's', v: movimiento.fecha };
  }

  private calcularIva(value: number) {
    const monto = Math.round(value * 100) / 100; // 2 decimal places
    return monto * 0.16; // 16% IVA
  }

}

