import { Component } from '@angular/core';
import { TableFacturacionComponent } from "./table-facturacion/table-facturacion.component";

import { SubMenuActiveButtonComponent } from "./sub-menu-active-button/sub-menu-active-button.component";
import { ToastyService } from './toasty-notification-component/services/toasty.service';
import { ToastyContainerComponent } from './toasty-notification-component/containers/toasty-container/toasty.container.component';
import { TableFacComisionComponent } from './table-fac-comision/table-fac-comision.component';


@Component({
    selector: 'app-pagos-facturacion',
    templateUrl: './pagos-facturacion.component.html',
    styleUrls: ['./pagos-facturacion.component.css'],
    imports: [
    TableFacturacionComponent,
    TableFacComisionComponent,
    SubMenuActiveButtonComponent,
    ToastyContainerComponent
]
})
export class PagosFacturacionComponent {
  typeFacturacion = 'pagos';
  titleSubMenu = 'Facturar Comisiones';
  constructor(
    private toastyService: ToastyService
  ) { }

  cambiarTipoFacturacion() {
    if (this.typeFacturacion === 'pagos') {
      this.typeFacturacion = 'comision';
      this.titleSubMenu = 'Facturar Pagos';
    }
    else {
      this.typeFacturacion = 'pagos';
      this.titleSubMenu = 'Facturar Comisiones';
    }
  }

  triggerToast(type: 'success' | 'error' | 'warning' | 'help') {
    const messages = {
      success: 'Operacion realizada con exito',
      error: 'Ha ocurrido un error',
      warning: 'Operacion invalida',
      help: 'Need assistance?'
    };

    this.toastyService.show(type, messages[type]);
  }

  pagosIcon = `
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="22" height="22"
    ><title>credit-card-outline</title>
    <path d="M20,8H4V6H20M20,18H4V12H20M20,4H4C2.89,4 2,4.89 2,6V18A2,2 0 0,0 4,20H20A2,2 0 0,0 22,18V6C22,4.89 21.1,4 20,4Z" fill="#f8e9ee"/>
    </svg>
  `;

  aperturasIcon = `
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="22" height="22">
    <title>credit-card-plus-outline</title>
    <path d="M21,18H24V20H21V23H19V20H16V18H19V15H21V18M19,8V6H3V8H19M19,12H3V18H14V20H3C1.89,20 1,19.1 1,18V6C1,4.89 1.89,4 3,4H19A2,2 0 0,1 21,6V13H19V12Z" fill='#be375d'/>
    </svg>
  `;

  activeFilters: any = {};

  onFiltersChanged(filters: any) {
    console.log('Received filters:', filters); // Debug log
    this.activeFilters = filters;
  }
}
