import { Component, EventEmitter, Input, Output, SimpleChanges, ViewChild } from '@angular/core';
import { PagoCargaMasiva } from '../../../models/pago.carga.masiva';
import { UtilsService } from '../../../services/utils.service';
import { CurrencyPipe, DatePipe, NgClass } from '@angular/common';
import { PagoCargaMasivaService } from '../../../controllers/pago.carga.masiva.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { ScrollingModule } from '@angular/cdk/scrolling';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-ventana-carga-masiva-cancelacion',
  imports: [
    FormsModule,
    DatePipe,
    CurrencyPipe,
    ScrollingModule,
    NgClass
  ],
  templateUrl: './ventana-carga-masiva-cancelacion.component.html',
  styleUrl: './ventana-carga-masiva-cancelacion.component.css'
})
export class VentanaCargaMasivaCancelacionComponent {  
  @Input() cargaMasivaEdit?: PagoCargaMasiva    
  @Output() cerrar = new EventEmitter<void>();
  nota: string = '';
  credito_id: number = 0  
  credito?: Credito  

  isAccordionOpen = true;
  isLoading: boolean = true;

  constructor(
    private creditoController: CreditoService,    
    private pagoCargaMasivaController: PagoCargaMasivaService,
    public pagoMasivoController: PagoCargaMasivaService,
    public utilsService: UtilsService,
  ) { }

  ngOnChanges(changes: SimpleChanges) { 
    this.isLoading = true;        
    if (changes['cargaMasivaEdit']) {          
      this.credito_id = this.cargaMasivaEdit?.credito_id ? this.cargaMasivaEdit?.credito_id : 0;      
      if (this.credito_id) {
        this.setCreditoById(this.credito_id).then(()=>{
            this.isLoading = false;                        
        });
      }
      else{         
        this.credito = undefined;                   
        this.isLoading = false;             
      }
    }        
  }
  

  async deleteCargaMasiva() {
    if(this.cargaMasivaEdit){
      if(await this.pagoCargaMasivaController.switch(this.cargaMasivaEdit, {nota: this.nota})){
        this.setCreditoById(this.credito!.id).then(()=>{
          this.cargaMasivaEdit = undefined
          this.cerrar.emit()
        })
      }
    }
    this.nota = '';    
  }

  private async setCreditoById(id: number) {
    this.credito_id = id
    this.credito = await this.creditoController.find(id, [
      'creditosPagos',
      'abonos',
      'abonos.pagosCargasMasivas',
      'abonos.usuarios',
      'productosFinancieros.plazos',
      'estadoCuenta',
      'datosPersonaFisica.datosPersonales',
      'datosPersonasMorales.representanteLegal',
      'convenios.conveniosPagos'])           
  }

  public async setCredito() {
    if (!this.credito && this.credito_id) {
      this.credito = await this.creditoController.find(this.credito_id, ['*']);
    }
  }

  sePagoDeMas() {    
     return (this.credito?.estado_cuenta?.monto_total_pagado ?? 0) > (this.credito?.estado_cuenta?.monto_total_mas_intereses ?? 0) && this.cargaMasivaEdit?.nota !== 'MIGRADO' 
  }  
}