import { Component } from '@angular/core';
import { PagoCargaMasiva } from '../../models/pago.carga.masiva';
import { PagoCargaMasivaService } from '../../controllers/pago.carga.masiva.service';
import { RowButtonClickEvent, TablaComponent, TableDefinition } from '../../shared/tabla/tabla.component';
import { FormularioFlotanteComponent } from "../../shared/formulario-flotante/formulario-flotante.component";
import { Conditional, Paginator } from '../../controllers/super.service';
import { FormsModule } from '@angular/forms';
import { CreditoAbono } from '../../models/credito.abono';
import { VentanaCargaMasivaCancelacionComponent } from './ventana-carga-masiva-cancelacion/ventana-carga-masiva-cancelacion.component';

const TABLE_DEF:TableDefinition = {
  style:{
    table:'table table-sm'
  },
  columns:[
    {
      header:'Fecha Abono',
      key:'fecha_abono',
      pipe:'date',
    },
    {
      header:'Monto',
      key:'importe_de_credito',
      pipe:'currency',
    },
    {
      header:'Referencia Bancaria',
      key:'descripcion',
    },
    'nota',
    {
      key:'creditos_abonos',
      keyList:['creditos','estado_cuenta','credito_status'],
      header:'Estado Credito',
    },
    {
      header:'Aplicado por',
      key:'creditos_abonos',
      function:(abono:CreditoAbono|undefined) =>{
        return abono?.usuarios?.nombre ?? 'N/A'
      }
    }
  ]
}

@Component({
    selector: 'app-carga-masiva-cancelacion',
    imports: [
    FormularioFlotanteComponent,    
    TablaComponent,
    FormsModule,
    VentanaCargaMasivaCancelacionComponent
],
    templateUrl: './carga-masiva-cancelacion.component.html',
    styleUrl: './carga-masiva-cancelacion.component.css'
})
export class CargaMasivaCancelacionComponent {
  tabla= TABLE_DEF
  cargasMasivas:PagoCargaMasiva[]=[]
  showEdit=false
  cargaMasivaEdit?:PagoCargaMasiva
  relations=[
    'creditosAbonos.creditos.estadoCuenta',
    'creditosAbonos.usuarios',
    'usuarios',
  ]
  mostrarTabla?:boolean=false
  filtros={
    estado:'',
    referencia:null,
    estado_credito:null,
    credito_id:0,
    monto:0,
    desde:null,
    hasta:null,
  }
  rowButtons = [{
    key: 'eliminar',
    text: '',   
    title: 'Eliminar', 
    style:{      
      button: 'btn btn-sm btn-danger scale-05',
      icon: 'bi bi-trash-fill'
    }
  }]

  getConditionals:Conditional[]=[
    {
      key:'deleted_at',
      operator:'IS NULL',
      value:null
    },
  ]

  getExtra:any={}

  constructor(
    public cargaMasivaController: PagoCargaMasivaService,
  ){}

  editarPago(pago: PagoCargaMasiva){
    this.cargaMasivaEdit = pago
    this.showEdit = true;
  }

  eliminarRow(row: RowButtonClickEvent<PagoCargaMasiva>){    
    this.editarPago(row.row)
  }

  public aplicarFiltros(){
    this.getExtra={
      filtro:JSON.stringify(this.filtros)
    }
    this.mostrarTabla=true
  }

  public limpiarFiltros(){
    this.filtros={
      estado:'',
      credito_id:0,
      estado_credito:null,
      referencia:null,
      monto:0,
      desde:null,
      hasta:null,
    }
    this.aplicarFiltros();
    this.mostrarTabla=false
  }

  onCerrarVentana() {
    this.showEdit = false;
    this.aplicarFiltros();
  }
}
