import { Component } from '@angular/core';
import { BitacoraCancelacionAbono } from '../../models/bitacora.cancelacion.abono';
import { BitacoraCancelacionAbonoService } from '../../controllers/bitacora.cancelacion..abono.service';
import { UtilsService } from '../../services/utils.service';
import { ActivatedRoute } from '@angular/router';
import { DataViewSectionComponent } from '../../shared/data-view-section/data-view.component';


@Component({
    selector: 'app-detalle-bitacora',
    imports: [
    DataViewSectionComponent
],
    templateUrl: './detalle-bitacora.component.html',
    styleUrl: './detalle-bitacora.component.css'
})
export class DetalleBitacoraComponent {
  bitacora?:BitacoraCancelacionAbono

  constructor(
    private bitacoraController: BitacoraCancelacionAbonoService,
    private utils:UtilsService,
    private route: ActivatedRoute,
  ){}

  ngOnInit(){
    this.route.paramMap.subscribe(async (params)=>{
      const id= this.utils.intOrNull(params.get('bitacora_id'))
      if(id){
        this.bitacora= await this.bitacoraController.find(id,["creditos","creditosAbonos.usuarios","pagosCargasMasivas","pagosCargasMasivas.usuarios","usuarios"])
      }
    })
  }
}
