
import { Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { IFactura } from '../../../models/facturacion/factura';
import { firstValueFrom } from 'rxjs';

@Component({
    selector: 'app-factura-masiva-modal',
    imports: [
    FormularioFlotanteComponent
],
    templateUrl: './factura-masiva-modal.component.html',
    styleUrl: './factura-masiva-modal.component.css'
})
export class FacturaMasivaModalComponent implements OnInit {

  @Input() show: boolean = false;
  @Output() showChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() tipoFactura?: string;
  @Input() datos?: any[];

  // -- funcion del padre
  @Output() callBackEvent: EventEmitter<any> = new EventEmitter<any>();

  totalDatos: number = 0;
  porcentaje: number = 0;
  facturaFails: IFactura[] = [];

  constructor(
    private api: ApiServiceService,
  ) { }

  ngOnInit(): void { }

  ngOnChanges() {
    console.log(this.datos, this.tipoFactura);

    this.totalDatos = this.datos?.length || 0;
  }

  async procesarFacturas() {
    console.log(this.datos);
    if (!this.datos) {
      return;
    }

    this.porcentaje = 0;
    let salto = Math.ceil(100 / this.datos.length);


    for (let dt of this.datos) {
      const { datos } = dt;

      console.log(datos);
      if (!datos.success) {
        this.facturaFails.push(dt);
        this.porcentaje += salto;
        continue;
      }
      const { concepto, datoscfdi, receptor } = dt;

      try {
        const result = await firstValueFrom<any>(
          this.api.post('factura/generar', {
            Receptor: receptor,
            Concepto: concepto,
            DatosCfdi: datoscfdi,
            credito_id: datos.creditoid ?? 0,
            abono_id: datos.abonoid ?? 0,
            tipo_factura: 'masivo'
          }, null, true)
        ); // -- firstValueFrom

        console.log(result);
        const { success, sicofi_response } = result;
        if (!success) {
          dt.datos.success = false;
          dt.datos.error = `${sicofi_response.CodigoError}: ${sicofi_response.ErrorCFDI}`;

          this.facturaFails.push(dt);
        }

        // -- para el progressbar
        this.porcentaje += salto;
      } catch (error) {
        // -- hubo un error en el servidor paramos todo
        console.log(error);
      }
    } // -- for

    this.callBackEvent?.emit();

    console.log(this.porcentaje);

  }

}
