  // #region -- factura individual
  facturar(credito: Credito): void {
    const rfc = this.utils.rfcFromCredito(credito);
    const cp = this.utils.getCpFiscal(credito);
    const nombre = this.utils.nombreFiscalClienteFromCredito(credito);
    const regimen = this.utils.getRegimenFiscalCodeFromCredito(credito);
    const fac_detalle = this.utils.getFacturacionDetalleFromCredito(credito);
    const email = this.utils.emailFromCredito(credito);

    if (!rfc || !cp) {
      this.toastyService.show(
        'error',
        'No se puede facturar, no se encontró el RFC o CP del cliente.',
      );
      return;
    }
    if (cp === undefined || cp === 0) {
      this.toastyService.show(
        'error',
        'No se puede facturar, el CP es inválido.',
      );
      return;
    }
    if (regimen === '0') {
      this.toastyService.show(
        'error',
        'No se puede facturar, el Régimen Fiscal es inválido.',
      );
      return;
    }

    // --  Revisar si ya existe una factura generada de comisión
    if (fac_detalle && fac_detalle.length > 0) {
      if (this.utils.existeFactura(fac_detalle, 'comision')) {
        this.toastyService.show(
          'error',
          'No se puede facturar, ya existe una factura generada.',
        );
        return;
      }
    }

    const { subtotal, iva, total } = this._getFacturaValues(credito);

    console.log(`Facturando ${credito.id} ${nombre} ${rfc} ${cp}`);
    console.log(`Subtotal: ${subtotal}, IVA: ${iva}, Total: ${total}`);

    const receptor: IReceptor = {
      Rfc: rfc,
      RazonSocial: nombre,
      UsoCFDI: 'G03',
      Pais: 'Mexico',
      Email: email ? email : '',
      RegimenFiscal: regimen,
      DomicilioFiscal: cp.toString().padStart(5, '0'),
    };

    const concepto: IConcepto = {
      ClaveProdServ: '84101700',
      ClaveUnidad: 'E48',
      Cantidad: 1,
      Unidad: 'PAGO',
      Descripcion: 'Comisión por apertura de crédito',
      Subtotal: subtotal,
      IvaRetenido: 0,
      IsrRetenido: 0,
      Descuento: 0,
      TotalIva: iva,
      ValorUnitario: subtotal,
      Importe: subtotal,
      ExentoIva: 0,
    };

    const datosCfdi: IDatosCfdi = {
      FormaPago: '03',
      Moneda: 'MXN',
      Subtotal: subtotal,
      Total: subtotal + iva,
      TotalIva: iva,
      Descuento: 0,
      CondicionesPago: 'Contado',
      Serie: 'A',
      TipodeComprobante: 'I',
      TipoCambio: 1,
      LugarDeExpedicion: '22010',
      MetodoPago: 'PUE',
    };

    this.api
      .post(
        'factura/generar',
        {
          Receptor: receptor,
          Concepto: concepto,
          DatosCfdi: datosCfdi,
          credito_id: credito.id,
          tipo_factura: 'comision',
          abono_id: 0,
        },
        null,
        true,
      )
      .subscribe((response: any) => {
        console.log('Factura generada', response);
        this.tabla?.getData();
      });
  }
