import { CommonModule } from '@angular/common';
import { Component, EventEmitter, input, Input, OnInit, Output } from '@angular/core';
import { FormularioFlotanteComponent } from '../../../shared/formulario-flotante/formulario-flotante.component';
import { Credito } from '../../../models/credito.model';
import { DatosFiscales } from '../../../models/datos.fiscales.model';
import { FacturacionDetalle } from '../../../models/facturacion.detalle.model';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { ToastyService } from '../toasty-notification-component/services/toasty.service';
import { UtilsService } from '../../../services/utils.service';
import { AbonoDistribuido } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';

interface IMotivoCancelacion {
  clave: string;
  descripcion: string;
}

@Component({
    selector: 'app-verificar-modal',
    imports: [
        CommonModule,
        FormularioFlotanteComponent,
    ],
    templateUrl: './verificar-modal.component.html',
    styleUrl: './verificar-modal.component.css'
})
export class VerificarModalComponent implements OnInit {

  constructor(
    private api: ApiServiceService,
    private toastyService: ToastyService,
    private utils: UtilsService,
  ) { }

  @Input() show: boolean = false;
  @Output() showChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  @Input() type: string = '';
  @Input() abonoId?: number;
  @Input() credito?: Credito;
  @Input() datoFiscal?: DatosFiscales;
  @Input() facturacionDetalle?: FacturacionDetalle[] = [];

  // -- Cancel
  @Output() cancelEvent: EventEmitter<any> = new EventEmitter<any>();

  title = 'Detalle Factura'
  monto_factura: number = 0;
  factura?: FacturacionDetalle;
  motivoCancelacion: IMotivoCancelacion[] = [
    // { clave: '01', descripcion: 'Comprobante emitido con errores con relación' },
    { clave: '02', descripcion: 'Comprobante emitido con errores sin relación' },
    { clave: '03', descripcion: 'No se llevo a cabo la operación' },
    { clave: '04', descripcion: 'Operación nominativa relacionada en una factura global' },
  ];
  showMotivo: boolean = false;
  motivo: string = '';

  ngOnInit(): void {
    console.log(this.datoFiscal);
  }

  ngOnChanges(): void {
    console.log(this.facturacionDetalle);

    this.monto_factura = 0;
    this.title = this.type === 'comision' ? 'Detalle Factura - Comisión' : 'Detalle Factura - Pago';

    if (this.credito) {
      if ( this.type === 'comision' ) {
        this.monto_factura = this.credito?.monto_autorizado ? this.credito.monto_autorizado * 0.015 : 0;
      } else {
        const estado_cuenta = this.credito?.estado_cuenta;
        if ( estado_cuenta && estado_cuenta.abonos_distribuidos ) {
          const abonosDist:  AbonoDistribuido[] = JSON.parse(estado_cuenta?.abonos_distribuidos as any);
          if ( abonosDist && abonosDist.length > 0 ) {
            this.monto_factura = abonosDist.find( (abono) => abono.abono.id === this.abonoId )?.pago_interes || 0;
          }
        }
      }
    }

    // -- buscar la factura tipo comision
    this.factura = this.type === 'comision' ?
        this.facturacionDetalle?.find((factura) => factura.tipo_factura === this.type) :
        this.facturacionDetalle?.find((factura) => factura.abono_id === this.abonoId );

    console.log('factura', this.factura);

  }

  downloadFactura(type: string) {
    console.log(this.factura);
    if (!this.factura) {
      this.toastyService.show('error', "No se encontró la factura.");
      return;
    }

    switch (type) {
      case 'xml':
        if ( !this.factura.xml_timbrado ) {
          this.toastyService.show('error', "No se encontró el XML");
          return;
        }
        this._downloadXml(this.factura.xml_timbrado, this.factura.uid_cicofi ? this.factura.uid_cicofi : 'factura_xml');
        break;

      case 'pdf':
        if ( !this.factura.uid_cicofi ) {
          this.toastyService.show('error', "No se encontró el UUID.");
          return;
        }
        this._downloadPdf(this.factura.uid_cicofi);
        break;
    }
  }

  showCancelacion() {
    this.showMotivo = !this.showMotivo;
  }

  onChangeMotivo(event: any) {
    const { value } = event.target;
    this.motivo = value;
  }

  procesarCancelacion() {
    this.api.post('factura/cancelar', {
      uuid: this.factura?.uid_cicofi,
      motivo: this.motivo,
    }, null, true)
      .subscribe((res: any) => {
        console.log(res);
        const { data } = res;
        if ( !data) {
          return;
        }

        if ( data.CancelacionCorrecta !== 'true' ) {
          this.toastyService.show('error', data.ErrorCancelacion);
          return;
        }
        this.toastyService.show('success', "La factura se canceló correctamente.");
        this.showMotivo = false;
        this.cancelEvent.emit(data);
      });
  }

  private _downloadXml(xmlString: string, uuid: string) {
    if (!xmlString) {
      this.toastyService.show('error', "No se encontró la factura.");
      return;
    }
    const blob = new Blob([xmlString], { type: 'text/xml' });
    const url = window.URL.createObjectURL(blob);
    const fileName = `${uuid}.xml`;

    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();

    window.URL.revokeObjectURL(url);
  }

  private _downloadPdf(uuid: string) {
    this.api.post('factura/pdf', { uuid }, null, true)
      .subscribe((res: any) => {
        console.log(res);
        const { data: { GeneraPDFCFDIV33Result } } = res;
        console.log(GeneraPDFCFDIV33Result);
        if (GeneraPDFCFDIV33Result.PDFCorrecto !== 'true') {
          this.toastyService.show('error', "No se generó correctamente la factura.");
          return;
        }

        let PDF = GeneraPDFCFDIV33Result.PDF;
        try {
          if (PDF.includes(',')) {
            PDF = PDF.split(',')[1];
          }
          const binaryData = atob(PDF);
          // Create an array buffer from the binary data
          const byteArray = new Uint8Array(binaryData.length);
          for (let i = 0; i < binaryData.length; i++) {
            byteArray[i] = binaryData.charCodeAt(i);
          }
          // Create a blob from the array buffer
          const blob = new Blob([byteArray], { type: 'application/pdf' });
          // Create a URL for the blob
          const url = window.URL.createObjectURL(blob);
          // Create a file name
          const fileName = `${uuid}.pdf`;

          const link = document.createElement('a');
          link.href = url;
          link.download = fileName;
          document.body.appendChild(link);
          link.click();

          document.body.removeChild(link);
        } catch (e) {
          console.error(e);
          this.toastyService.show('error', "No se generó correctamente la factura.");
        }
      });
  }

  public testTriggerCancel() {
    this.cancelEvent.emit({
      uuid: '1234567890',
      motivo: 'Comprobante emitido con errores con relación',
    });
  }

}
