import { Component } from '@angular/core';
import { ActivatedRoute, NavigationEnd, Router, Event, RouterOutlet } from '@angular/router';
import { BuscadorCreditosComponent } from "../../main/estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { filter, Subject, takeUntil } from 'rxjs';

@Component({
    selector: 'app-main',
    imports: [
        RouterOutlet,
        BuscadorCreditosComponent
    ],
    templateUrl: './main.component.html',
    styleUrl: './main.component.css'
})
export class MainComponent {
  creditoId:number=0
  title = 'Tesorería'; // Valor por defecto
  currentPath = '/main/';
  private destroy$ = new Subject<void>();

  constructor(
    private route: ActivatedRoute,
    private router: Router
  ) {}

  ngOnInit() {
    // Observar cambios en la ruta activa (incluyendo hijos)
    this.router.events.pipe(
      filter((event: Event): event is NavigationEnd => event instanceof NavigationEnd),
      takeUntil(this.destroy$)
    ).subscribe(() => {
      this.updateFromChildRoute();
    });

    // Actualizar al iniciar
    this.updateFromChildRoute();
  }

  private updateFromChildRoute() {
    let child = this.route.firstChild;
    while (child?.firstChild) {
      child = child.firstChild; // Navegar hasta el último hijo activo
    }

    // Obtener título de la ruta más profunda
    child?.title.subscribe(title => {
      this.title = title || 'Tesorería';
    });

    // Obtener path de la ruta más profunda
    child?.url.subscribe(urlSegments => {
      if (urlSegments.length > 0 && typeof urlSegments[0].path =='string') {
        this.currentPath = '/pagos/main/'+ urlSegments[0].path;
      }
    });
  }

  ngOnDestroy() {
    this.destroy$.next();
    this.destroy$.complete();
  }

  onCreditoChange(){
    const url= this.route.snapshot.url
    this.router.navigate([this.currentPath,this.creditoId])
  }
}
