import { Component, Input } from '@angular/core';

import { DomSanitizer, SafeHtml } from '@angular/platform-browser';

@Component({
    selector: 'app-sub-menu-active-button',
    imports: [],
    templateUrl: './sub-menu-active-button.component.html',
    styleUrls: ['./sub-menu-active-button.component.css']
})
export class SubMenuActiveButtonComponent {
  @Input() label: string = 'Button';

  private _svgIcon: string = '';
  safeSvgIcon: SafeHtml = '';

  constructor(private sanitizer: DomSanitizer) {}

  @Input() set svgIcon(value: string) {
    this._svgIcon = value;
    this.safeSvgIcon = this.sanitizer.bypassSecurityTrustHtml(value);
  }
}
