import { Injectable } from '@angular/core';
import { UtilsService } from '../../../services/utils.service';
import { IFactura, IDatosFactura } from '../../../models/facturacion/factura';
import { CreditoAbono } from '../../../models/credito.abono';
import { Credito } from '../../../models/credito.model';
import { AbonoDistribuido } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { IConcepto } from '../../../models/facturacion/concepto';
import { IDatosCfdi } from '../../../models/facturacion/datoscfdi';
import { IReceptor } from '../../../models/facturacion/receptor';
import { EstadoCuenta } from '../../../models/estado.cuenta';

@Injectable({
  providedIn: 'root',
})
export class FacturaMasivaService {
  constructor(private utils: UtilsService) {}

  checkDatosFiscales(creditos: Credito[]) {
    for (const credito of creditos) {
      const datosFiscales = this.utils.getDatosFiscalesFromCredito(credito);

      if (!datosFiscales) {
        return false;
      } else {
        // -- revisar si tiene Razón Socia, RFC, Régimen Fiscal y Código Postal
        const razonSocial = this.utils.getRazonSocialFromCredito(credito);
        if (razonSocial === '' || razonSocial === 'N/A') {
          return false;
        }
        const rfc = this.utils.rfcFromCredito(credito);
        if (rfc === '' || rfc === 'N/A') {
          return false;
        }
        const cp = this.utils.getCp(credito);
        if (cp === '' || cp === 'N/A') {
          return false;
        }
        const regimenCode = this.utils.getRegimenFiscalCodeFromCredito(credito);
        if (regimenCode === '' || regimenCode === 'N/A') {
          return false;
        }
      }
    }
    return true;
  }

  checkTieneFacturaComsionSel(seleccionados: Credito[]) {
    for (let sel of seleccionados) {
      const fac_detalle = this.utils.getFacturacionDetalleFromCredito(sel);
      if (fac_detalle) {
        if (this.utils.existeFactura(fac_detalle, 'comision')) {
          return true;
        }
      }
    }
    return false;
  }

  generarDatosFacturaComision(datos: Credito[]): IFactura[] {
    let datosFactura: IFactura[] = [];
    for (let d of datos) {
      console.log(d);

      const email = this.utils.emailFromCredito(d);
      const cp = this.utils.getCpFiscal(d);

      let df = this._getAndVerificar(d, 0, true);
      if (df.success) {
        // -- algo
        const { subtotal, iva, total } = this.getFacturaValues(d);
        const receptor: IReceptor = {
          Rfc: df.rfc,
          RazonSocial: df.nombre,
          UsoCFDI: 'G03',
          Pais: 'Mexico',
          Email: email ? email : '', //
          RegimenFiscal: df.regimen,
          DomicilioFiscal: cp.toString().padStart(5, '0'),
        };

        const concepto: IConcepto = {
          ClaveProdServ: '84101700',
          ClaveUnidad: 'E48',
          Cantidad: 1,
          Unidad: 'PAGO',
          Descripcion: 'Comisión por apertura de crédito',
          Subtotal: subtotal,
          IvaRetenido: 0,
          IsrRetenido: 0,
          Descuento: 0,
          TotalIva: iva,
          ValorUnitario: subtotal,
          Importe: subtotal,
          ExentoIva: 0,
        };

        const datosCfdi: IDatosCfdi = {
          FormaPago: '03',
          Moneda: 'MXN',
          Subtotal: subtotal,
          Total: total, // subtotal + iva,
          TotalIva: iva,
          Descuento: 0,
          CondicionesPago: 'Contado',
          Serie: 'A',
          TipodeComprobante: 'I',
          TipoCambio: 1,
          LugarDeExpedicion: '22010',
          MetodoPago: 'PUE',
        };

        datosFactura.push({
          receptor,
          concepto,
          datoscfdi: datosCfdi,
          datos: df,
        });
      } else {
        df.error = 'Los datos fiscales no son válidos';
        datosFactura.push({
          datos: df,
        });
      }
    }

    return datosFactura;
  }

  generarDatosFacturaPagos(datos: CreditoAbono[]): IFactura[] {
    console.log(datos);

    let datosFactura: IFactura[] = [];
    // -- procesamos los datos
    for (let d of datos) {
      if (d.creditos) {
        const email = this.utils.emailFromCredito(d.creditos);
        const cp = this.utils.getCpFiscal(d.creditos);
        let df = this._getAndVerificar(d.creditos, d.id);

        if (df.success) {
          const pagoInteres = this.getAbonosDistrField(d, 'interes');
          const pagoIva = this.getAbonosDistrField(d, 'iva');

          if (pagoInteres == 0 || pagoIva == 0) {
            df.success = false;
            df.error =
              'No se puede generar la factura, no hay monto a facturar';
            datosFactura.push({
              datos: df,
            });
            continue;
          }

          const calFactura = this.calculoFactura(pagoInteres);

          const receptor: IReceptor = {
            Rfc: df.rfc,
            RazonSocial: df.nombre,
            UsoCFDI: 'G03',
            Pais: 'Mexico',
            Email: email ? email : '', // "lcc.manuel@gmail.com",// item.email,
            RegimenFiscal: df.regimen,
            DomicilioFiscal: cp.toString().padStart(5, '0'),
          };

          const concepto: IConcepto = {
            ClaveProdServ: '84101700',
            ClaveUnidad: 'E48',
            Cantidad: 1,
            Unidad: 'PAGO',
            Descripcion: 'Pago por Interes',
            Subtotal: calFactura.subtotal, // pagoInteres
            IvaRetenido: 0,
            IsrRetenido: 0,
            TotalIva: calFactura.iva, // pagoIva
            Descuento: 0,
            ValorUnitario: calFactura.subtotal, // pagoInteres
            Importe: calFactura.subtotal, // pagoInteres
            ExentoIva: 0,
          };

          const datosCfdi: IDatosCfdi = {
            FormaPago: '03',
            Moneda: 'MXN',
            Subtotal: calFactura.subtotal,
            Total: calFactura.total,
            TotalIva: pagoIva,
            Descuento: 0,
            CondicionesPago: 'Contado',
            Serie: 'A',
            TipodeComprobante: 'I',
            TipoCambio: 1,
            LugarDeExpedicion: '22010',
            MetodoPago: 'PUE',
          };

          datosFactura.push({
            receptor,
            concepto,
            datoscfdi: datosCfdi,
            datos: df,
          });
        } // -- if (d.success)
        else {
          df.error = 'Los datos fiscales no son válidos';
          datosFactura.push({
            datos: df,
          });
        }
      } // -- if (d.creditos)
    } // -- for (let d of datos)

    return datosFactura;
  }

  getFacturaValues(credito: Credito): {
    subtotal: number;
    iva: number;
    total: number;
  } {
    const roundDesc = 100;

    const comision = credito.monto_autorizado
      ? credito.monto_autorizado * 0.015
      : 0;

    let subtotal = comision; // comision / 1.16;// Number((comision / 1.16).toFixed(2));
    let iva = subtotal * 0.16;
    let total = subtotal + iva;

    // -- Redondear los valores
    subtotal = Math.round(subtotal * roundDesc) / roundDesc;
    iva = Math.round(iva * roundDesc) / roundDesc;
    total = Math.round(total * roundDesc) / roundDesc;

    return { subtotal, iva, total };
  }

  private _getAndVerificar(
    credito: Credito,
    abonoId: number,
    comision: boolean = false,
  ): IDatosFactura {
    console.log(credito);

    let datosFactura: IDatosFactura = {
      creditoid: credito.id,
      abonoid: abonoId,
      rfc: '',
      cp: '',
      nombre: '',
      regimen: '',
      success: false,
    };

    const rfc = this.utils.rfcFromCredito(credito);
    const cp = this.utils.getCp(credito);
    const nombre = this.utils.nombreFiscalClienteFromCredito(credito);
    const regimenCode = this.utils.getRegimenFiscalCodeFromCredito(credito);
    const fac_detalle = this.utils.getFacturacionDetalleFromCredito(credito);

    // -- Validar si extehnde el RFC y el CP
    // TODO: Revisar la validación
    if (!rfc || !cp) {
      datosFactura.rfc = '';
      datosFactura.cp = '';
    } else {
      datosFactura.rfc = rfc;
      datosFactura.cp = cp;
      datosFactura.success = true;
    }
    // -- Validar si es válido el CP
    if (cp === '00000' || cp === '0') {
      datosFactura.cp = '';
    } else {
      datosFactura.cp = cp;
      datosFactura.success = true;
    }
    // -- Validar si existe el regimen
    if (regimenCode === '0') {
      datosFactura.regimen = '';
    } else {
      datosFactura.regimen = regimenCode;
      datosFactura.success = true;
    }
    // -- Validar si existe el abonoId en la lista de facturas
    if (!comision) {
      if (fac_detalle && fac_detalle.length > 0) {
        if (this.utils.existeFacturaPorAbonoId(fac_detalle, abonoId)) {
          datosFactura.success = false;
        } else {
          datosFactura.success = true;
        }
      }
    }

    datosFactura.nombre = nombre;

    return datosFactura;
  }

  getAbonosDistrField(abono: CreditoAbono, field: string): number {
    const estadoCuenta = abono.creditos?.estado_cuenta;
    const abonosDistribuidos: AbonoDistribuido[] = JSON.parse(
      estadoCuenta?.abonos_distribuidos as any,
    );
    switch (field) {
      case 'capital':
        return (
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)
            ?.pago_capital || 0
        );

      case 'interes':
        return (
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)
            ?.pago_interes || 0
        );

      case 'iva':
        return (
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)?.pago_iva ||
          0
        );

      default:
        return 0;
    }
  }

  calculoFactura(sub: number): {
    subtotal: number;
    iva: number;
    total: number;
  } {
    const roundDesc = 100;
    const subT = Math.round(sub * roundDesc) / roundDesc;
    const iva = Math.round(subT * 0.16 * roundDesc) / roundDesc;

    const total = subT + iva;

    return {
      subtotal: subT,
      iva,
      total,
    };
  }
}
