import { Component, EventEmitter, OnInit, ViewChild } from '@angular/core';
import { PolizaHelperService } from '../pagos-facturacion/services/poliza-helper.service';
import { CreditoAbono } from '../../models/credito.abono';
import { FormsModule } from '@angular/forms';

import { UtilsHelper } from '../pagos-facturacion/helpers/Utils.helpers';
import { ToastyService } from '../pagos-facturacion/toasty-notification-component/services/toasty.service';
import { ToastyContainerComponent } from '../pagos-facturacion/toasty-notification-component/containers/toasty-container/toasty.container.component';
import { PolizaInfo, PolizaItemsInteres } from '../../models/poliza.items';
import { Credito } from '../../models/credito.model';
import { Sesion } from '../../models/sesion.model';
import { AdvancedSearchFilter, RowButtonClickEvent, TablaComponent, TableDefinition } from '../../shared/tabla/tabla.component';
import { CreditoService } from '../../controllers/credito.service';
import { Conditional } from '../../controllers/super.service';
import { UtilsService } from '../../services/utils.service';
import { UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { Form, GenericFormComponent } from '../../shared/generic-form/generic-form.component';
import { FormularioFlotanteComponent } from '../../shared/formulario-flotante/formulario-flotante.component';

const TABLE_DEF: TableDefinition = {
  style: {
    table: 'table table-sm table-striped table-bordered',
  },
  columns: [
    { key: 'id', header: 'No Crédito', style: { td: 'text-center' } },
    {
      key: 'row', header: 'Acreditado',
      function: (credito: Credito, utils: UtilsService) => {
        return utils.nombreClienteFromCredito(credito);
      }
    },
    {
      key: 'row', header: 'Referencia Bancaria',
      function: (credito: Credito) => {
        return credito.referencia_bancaria || '';
      }
    },
    {
      key: 'row', header: 'Monto Autorizado',
      function: (credito: Credito) => {
        return credito.monto_autorizado?.toLocaleString('en-MX', { style: 'currency', currency: 'MXN' });
      },
      style: { td: 'text-end' }
    },
    {
      key: 'row', header: 'Cuenta Contable',
      function: (credito: Credito) => {
        return credito.cuenta_contable || 'No Asignada';
      }
    },
  ]
}

const FORM_DEF: Form = [
  {
    title: 'Editar Cuenta Contable',
    fields: [
      { key: 'cuenta_contable', label: 'Cuenta Contable', type: 'text', validator: { required: true }, style: { input: 'form-control w-100' } },
    ]
  },
];

@Component({
    selector: 'app-polizas',
    imports: [
    FormsModule,
    ToastyContainerComponent,
    TablaComponent,
    FormularioFlotanteComponent,
    GenericFormComponent
],
    templateUrl: './polizas.component.html',
    styleUrl: './polizas.component.css'
})
export class PolizasComponent implements OnInit {

  data: CreditoAbono[] = []
  dataCreditos: Credito[] = [];
  polizasItems: PolizaItemsInteres[] = [];

  fechaInicial = '';
  fechaFinal = '';
  fechaPoliza: string = '';
  tipoPoliza = 'interes';
  sesionId: string = '';
  form: Form = FORM_DEF;
  credito?: Credito;
  creditoChange: EventEmitter<Credito> = new EventEmitter<Credito>();
  showForm: boolean = false;

  esPolizaCredito: boolean = false;
  showTablaCreditos: boolean = false;
  selectedCreditos: Credito[] = [];

  sesiones: Sesion[] = [];

  @ViewChild('tabla') tabla: TablaComponent<Credito> | undefined;
  tableDef = TABLE_DEF;
  tablaAdvancedFilters: AdvancedSearchFilter[] = [];
  tablaConditionals: Conditional[] = [];

  constructor(
    public creditoController: CreditoService,
    private polizaHelper: PolizaHelperService,
    private toasty: ToastyService,
  ) {
    const monthDates = UtilsHelper.getCurrentMonthDates();
    this.fechaInicial = monthDates.start;
    this.fechaFinal = monthDates.end;
    this.fechaPoliza = new Date().toISOString().split('T')[0];
  }

  ngOnInit(): void {
    this.creditoChange.subscribe((credito: Credito) => {
      console.log('Credito cambiado:', credito);
    });
  }

  onRowButtonClickEvent(event: RowButtonClickEvent<Credito>) {
    const { key, row } = event;
    switch (key) {
      case 'editar_cta_contable':
        console.log(row);
        this.credito = row;
        this.showForm = true;

        break;

      default:
        console.warn('No se ha definido una acción para este botón:', key);
    }

  }

  async generarPoliza() {
    console.log(this.fechaInicial, this.fechaFinal, this.tipoPoliza);
    if (!this.tipoPoliza || !this.fechaInicial || !this.fechaInicial) {
      this.toasty.show('error', 'Debe seleccionar una fecha inicial, final y el tipo de póliza');
      return;
    }

    switch (this.tipoPoliza) {
      case 'interes':
        // -- Procesar datos para interes
        const polizaInfo: PolizaInfo = {
          fecha: this.fechaPoliza.replace(/-/g, ''),  // new Date().toISOString().split('T')[0].replace(/-/g, ''),
          tipoPol: 14,
          folio: 1,
          concepto: `INTERES`,
          guid: '00000000-0000-0000-0000-000000000000'
        }
        this.data = await this.polizaHelper.procesarDatosPolizaInteres(this.fechaInicial, this.fechaFinal);
        this.polizasItems = this.polizaHelper.filtrarPagosInteres(this.data);

        console.log(this.polizasItems);
        if (this.polizasItems.length === 0) {
          this.toasty.show('error', 'No se encontraron pagos de interés para generar la póliza');
          return;
        }
        await this.polizaHelper.generarPolizaInteres(polizaInfo, this.polizasItems)

        break;

      case 'creditos':
        if (this.selectedCreditos.length === 0) {
          this.toasty.show('error', 'Debe seleccionar al menos un crédito para generar la póliza, consulta los créditos a seleccionar');
          return;
        }

        const polizaCredito: PolizaInfo = {
          fecha: this.fechaPoliza.replace(/-/g, ''),
          tipoPol: 8,
          folio: 1,
          concepto: 'ENTREGA DE CREDITOS EMPRENDE',
          guid: ''
        }

        let polizaItemsCreditos = this.polizaHelper.filtrarFacturaCreditos(this.selectedCreditos);
        if (polizaItemsCreditos.length === 0) {
          this.toasty.show('error', 'No se encontraron datos procesados de créditos para generar la póliza');
          return;
        }
        console.log(polizaItemsCreditos);

        await this.polizaHelper.generarPolizaCreditos(polizaCredito, polizaItemsCreditos);
        break;

      case 'ingresos': // INFO: Son las comsiones de los créditos facturados
        const poliza: PolizaInfo = {
          fecha: new Date().toISOString().split('T')[0].replace(/-/g, ''),
          tipoPol: 1,
          folio: 1,
          concepto: `COBRANZA`,
          guid: '00000000-0000-0000-0000-000000000000'
        }

        this.dataCreditos = await this.polizaHelper.procesarDatosPolizaComision(this.fechaInicial, this.fechaFinal);
        let polizaItems = this.polizaHelper.filtrarFacturaComision(this.dataCreditos);

        if (polizaItems.length === 0) {
          this.toasty.show('error', 'No se encontraron datos de factura de comisiones para generar la póliza');
          return;
        }

        // -- Generando la póliza de ingresos
        this.polizaHelper.generarPolizaIngresos(poliza, polizaItems);
        break;
    }
  } // async generarPoliza()

  // -- Para la seleccionar créditos y conciliarlos
  async consultarCreditos() {
    // const data = this.polizaHelper.procesarDatosPolizaCreditos(this.fechaInicial, this.fechaFinal);
    // console.log(data);

    this.showTablaCreditos = true;
    this.tablaConditionals = [
      { key: 'liberado_fecha', operator: '>=', value: this.fechaInicial },
      { key: 'liberado_fecha', operator: '<=', value: this.fechaFinal },
    ]
    this.tablaAdvancedFilters = [];
  }

  selectTipPoliza(event: any) {
    if (event.target.value === 'creditos') {
      this.esPolizaCredito = true;
    } else {
      this.esPolizaCredito = false;
    }
    console.log(event.target.value);
  }

  async getSesiones() {
    this.sesiones = await this.polizaHelper.getListadoSesiones();    
  }

}
