import { Component } from '@angular/core';
import { PagoCargaMasiva } from '../../models/pago.carga.masiva';
import { PagoCargaMasivaService } from '../../controllers/pago.carga.masiva.service';
import { TablaComponent, TableDefinition } from '../../shared/tabla/tabla.component';
import { FormularioFlotanteComponent } from "../../shared/formulario-flotante/formulario-flotante.component";
import { EditarCargaMasivaComponent } from "../carga-masiva/editar-carga-masiva/editar-carga-masiva.component";
import { Conditional } from '../../controllers/super.service';
import { FormsModule } from '@angular/forms';
import { CreditoAbono } from '../../models/credito.abono';

const TABLE_DEF:TableDefinition = {
  style:{
    table:'table table-sm'
  },
  columns:[
    {
      header:'Fecha Abono',
      key:'fecha_abono',
      pipe:'date',
    },
    {
      header:'Monto',
      key:'importe_de_credito',
      pipe:'currency',
    },
    {
      header:'Referencia Bancaria',
      key:'descripcion',
    },
    'nota',
    {
      key:'creditos_abonos',
      keyList:['creditos','estado_cuenta','credito_status'],
      header:'Estado Credito',
    },
    {
      header:'Aplicado por',
      key:'creditos_abonos',
      function:(abono:CreditoAbono|undefined) =>{
        return abono?.usuarios?.nombre ?? 'N/A'
      }
    }
  ]
}

@Component({
    selector: 'app-pagos-no-identificados',
    imports: [
    FormularioFlotanteComponent,
    EditarCargaMasivaComponent,
    TablaComponent,
    FormsModule
],
    templateUrl: './pagos-no-identificados.component.html',
    styleUrl: './pagos-no-identificados.component.css'
})
export class PagosNoIdentificadosComponent {
  tabla= TABLE_DEF
  cargasMasivas:PagoCargaMasiva[]=[]
  showEdit=false
  cargaMasivaEdit?:PagoCargaMasiva
  showDeleteModal = false;
  deleteNote = '';
  pagoToDelete: PagoCargaMasiva | null = null;
  relations=[
    'creditosAbonos.creditos.estadoCuenta',
    'creditosAbonos.usuarios',
    'usuarios',
  ]
  mostrarTabla?:boolean=false
  filtros={
    estado:'',
    referencia:null,
    estado_credito:null,
    credito_id:0,
    monto:0,
    desde:null,
    hasta:null,
  }

  getConditionals:Conditional[]=[
    {
      key:'deleted_at',
      operator:'IS NULL',
      value:null
    },
  ]

  getExtra:any={}

  constructor(
    public cargaMasivaController: PagoCargaMasivaService,
  ){}


  editarPago(pago: PagoCargaMasiva) {
    this.cargaMasivaEdit=pago
    this.showEdit=true
  }

  public aplicarFiltros(){
    this.getExtra={
      filtro:JSON.stringify(this.filtros)
    }
    this.mostrarTabla=true
  }

  public limpiarFiltros(){
    this.filtros={
      estado:'',
      credito_id:0,
      estado_credito:null,
      referencia:null,
      monto:0,
      desde:null,
      hasta:null,
    }
    this.aplicarFiltros();
    this.mostrarTabla=false
  }
}
