import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { Toasty } from '../models/toasty.model';

@Injectable({
  providedIn: 'root'
})
export class ToastyService {
  private _toasts = new BehaviorSubject<Toasty[]>([]);
  public toasts$ = this._toasts.asObservable();

  private counter = 0;

  show(type: Toasty['type'], message: string, title?: string) {
    const id = ++this.counter;
    const newToast: Toasty = { id, type, message, title };
    this._toasts.next([...this._toasts.getValue(), newToast]);
  }

  remove(id: number) {
    const currentToasts = this._toasts.getValue();
    this._toasts.next(currentToasts.filter(toast => toast.id !== id));
  }
}

