import { Component, inject, ViewChild } from '@angular/core';
import { LiquidacionAnticipada } from '../../models/liquidacion.anticipada.model';
import { LiquidacionAnticipadaService } from '../../controllers/liquidacion.anticipada.service';
import { ActivatedRoute } from '@angular/router';
import { FormsModule } from '@angular/forms';
import { BuscadorCreditosComponent } from "../../main/estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { Credito } from '../../models/credito.model';
import { Periodo, UtilsEstadoCuentaService } from '../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { UtilsService } from '../../services/utils.service';
import { CurrencyPipe } from '@angular/common';
import { CreditoAbonoService } from '../../controllers/credito.abono.service';
import { BitacoraCancelacionAbonoService } from '../../controllers/bitacora.cancelacion..abono.service';
import { CreditoService } from '../../controllers/credito.service';
import { VanillaDialogService } from '../../services/vanilla-dialog/vanilla-dialog.service';
import { firstValueFrom } from 'rxjs';
import { FileInputComponent } from '../../shared/file-input/file-input.component';

@Component({
  selector: 'app-liquidacion-anticipada',
  imports: [
    FormsModule,
    BuscadorCreditosComponent,
    CurrencyPipe,
    FileInputComponent,
  ],
  templateUrl: './liquidacion-anticipada.component.html',
  styleUrl: './liquidacion-anticipada.component.css'
})
export class LiquidacionAnticipadaComponent {
  @ViewChild('fileInput') fileInput?: FileInputComponent;
  liquidacion: Partial<LiquidacionAnticipada> = {}
  credito?: Credito
  periodoSelected?: Periodo
  relations = [
    'estadoCuenta',
    'abonos',
    'convenios',
    'convenios.conveniosPagos',
    'creditosPagos'
  ]

  showCancelacionForm = false;
  public comentarioCancelacion: string = '';

  private liquidacionAnticipadaController = inject(LiquidacionAnticipadaService)
  private creditoController = inject(CreditoService)
  private creditoAbonoController = inject(CreditoAbonoService)
  private detalleBitacoraController = inject(BitacoraCancelacionAbonoService)
  private utilsEstadoCuenta = inject(UtilsEstadoCuentaService)
  private dialog = inject(VanillaDialogService)
  public utils = inject(UtilsService)
  private route = inject(ActivatedRoute)

  ngOnInit() {
    this.route.params.subscribe(async params => {
      const id = params['liquidacion_id']
      if (id) {
        const data = await this.liquidacionAnticipadaController.find(id, {
          relations: ['*'],
        })
        this.liquidacion = data ? data : {}
        this.liquidacion.fecha = this.liquidacion.fecha?.substring(0, 10)
        console.log(this.liquidacion)
        this.credito = await this.creditoController.find(this.liquidacion.credito_id!, this.relations)
      }
    })
  }

  public onSubmit() {
    if (!this.liquidacion.id) {
      this.liquidacion.credito_id = this.credito?.id!
      this.liquidacion.credito_abono_id = this.abonoPeriodoCondonado?.id!
    }

  }

  get sePuedeLiquidarAnticipadaMente() {
    if (!this.credito || !this.credito.abonos || !this.credito.estado_cuenta) return false;
    const estadoCuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(this.credito)!

    if (!estadoCuenta.abonos_distribuidos?.length) return false;

    return estadoCuenta.abonos_distribuidos.some(abono => {
      const interes_pagado = (+abono.pago_interes + +abono.pago_iva)

      return interes_pagado >= estadoCuenta.capital_por_vencer
    })
  }

  get periodos(): Periodo[] {
    const estadoCuenta = this.utilsEstadoCuenta.calculateEstadoDeCuenta(this.credito)!
    return estadoCuenta.periodos.filter(p => p.status !== 'VIGENTE')
  }

  get abonoPeriodoCondonado() {
    return this.periodoSelected?.abonos?.find(a => a.pago_interes)?.abono
  }

  public setLiquidacion() {
    if (!this.periodoSelected) return;
    this.liquidacion.iva_condonado = this.periodoSelected.iva
    this.liquidacion.interes_condonado = this.periodoSelected.interes
    this.liquidacion.capital_adelantado = this.periodoSelected.iva + this.periodoSelected.interes + (this.periodoSelected.abonos?.reduce((acc, a) => acc + +a.abono.monto, 0) ?? 0)
  }

  public async ejecutarCondonacion() {
    if (!this.liquidacion.iva_condonado || !this.liquidacion.interes_condonado || !this.periodoSelected || !this.credito) return;
    if(!this.esPeriodoValido()){
      await firstValueFrom(this.dialog.show({
        title:'Advertencia',
        body: 'El periodo seleccionado no contiene capital adelantado y no podra liquidar el cŕedito de manera anticipada, por favor elige otro.',
        tipo:'warning'
      }))
      return
    }

    const fechaPeriodo = new Date(this.liquidacion.fecha!.substring(0, 10) + 'T17:00:00Z')
    const fechaAbono = fechaPeriodo.getFullYear() + '-' +
      (fechaPeriodo.getMonth() + 1).toString().padStart(2, '0') + '-01';
      
    const abono = await this.creditoAbonoController.new({
      monto: this.liquidacion.iva_condonado! + this.liquidacion.interes_condonado!,
      fecha: fechaAbono,
      credito_id: this.credito.id,
      comentarios: 'SYSTEM: CONDONACION DE INTERESES ORDINARIOS POR LIQUIDACION TEMPRANA',
      concepto: 'CONDONACION DE INTERESES',
    })    

    this.liquidacion.credito_abono_id = abono!.id
    this.liquidacion.credito_id = this.credito.id

    this.liquidacion = (await this.liquidacionAnticipadaController.new(this.liquidacion))!

    if (this.fileInput?.file) {
      if(this.liquidacion.id){
        this.fileInput.apiUrl = `api/liquidaciones_anticipadas/${this.liquidacion.id}/file`;
        await this.fileInput.upload();
      }      
    }

    await this.detalleBitacoraController.new({
      credito_id: this.liquidacion.credito_id,
      creditos_abono_id: this.liquidacion.credito_abono_id,
      pagos_cargas_masiva_id: null,
      origen: 'LIQUIDACION ANTICIPADA',
      accion: 'CONDONACION DE INTERES ORDINARIO',
      motivo: this.liquidacion.comentarios,
      usuario_id: this.liquidacion.usuario_id
    })

    this.creditoController.actualizarEstadoCuenta(this.credito)
  }

  esPeriodoValido(){
    if(!this.periodoSelected) return false;
    return this.periodoSelected.abonos?.some(a => a.adelantado >0)
  }

  public async cancelarCondonacion() {
    if (!this.liquidacion.id) return;
    await this.creditoAbonoController.switch(this.liquidacion.credito_abono_id!, { nota: "SYSYEM: CANCELACIÓN AUTOMATICA POR CANCELACION LIQUIDACION ANTICIPADA" })
    this.liquidacionAnticipadaController.switch(this.liquidacion.id)

    await this.detalleBitacoraController.new({
      credito_id: this.liquidacion.credito_id,
      creditos_abono_id: this.liquidacion.credito_abono_id,
      pagos_cargas_masiva_id: null,
      origen: 'LIQUIDACION ANTICIPADA',
      accion: 'CANCELACION',
      motivo: this.comentarioCancelacion,
    })

    this.creditoController.actualizarEstadoCuenta(this.credito)
  }

  public isLiquidacionValid() {
    return this.periodoSelected && this.liquidacion.fecha && this.liquidacion.comentarios && this.fileInput?.file && !this.liquidacion.deleted_at && !this.liquidacion.id
  }
}
