
export class UtilsHelper {

  constructor() { }

  public static getCurrentMonthDates(): { start: string, end: string } {
    const today = new Date();

    // First day of the current month (YYYY-MM-01)
    const firstDay = new Date(today.getFullYear(), today.getMonth(), 1);

    // Last day of the current month (YYYY-MM-DD)
    const lastDay = new Date(today.getFullYear(), today.getMonth() + 1, 0);

    // Format dates as YYYY-MM-DD
    const startStr = firstDay.toISOString().split('T')[0];
    const endStr = lastDay.toISOString().split('T')[0];

    return { start: startStr, end: endStr };
  }

  public static getExtra(tipo: string, column: string = 'fecha', tipoFac: string = 'pagos') {
    let extra = {
      sort: JSON.stringify({ column, desc: true }),
      filtro: '',
    }

    switch (tipo) {
      case "1":
        extra.filtro = tipoFac == 'pagos' ?
          JSON.stringify({ listos_para_facturar: true }) :
          'listos_para_facturar';
        break;

      case "2":
        extra.filtro = tipoFac === 'pagos' ?
          JSON.stringify({ no_listos_para_facturar: true }) :
          'no_listos_para_facturar';
        break;

      case "3":
        extra.filtro = tipoFac === 'pagos' ?
          JSON.stringify({ facturados: true }) :
          'facturados';
    }

    return extra;
  }

}
