import { Routes } from "@angular/router";
import { ListCreditosPagosComponent } from "./list-creditos-pagos/list-creditos-pagos.component";
import { AbonoComponent } from "./abono/abono.component";
import { ListBitacoraCancelacionesComponent } from "./list-bitacora-cancelaciones/list-bitacora-cancelaciones.component";
import { DetalleBitacoraComponent } from "./detalle-bitacora/detalle-bitacora.component";
import { MainComponent } from "./main/main.component";
import { PagosNoIdentificadosComponent } from "./pagos-no-identificados/pagos-no-identificados.component";
import { PagosFacturacionComponent } from "./pagos-facturacion/pagos-facturacion.component";
import { PolizasComponent } from "./polizas/polizas.component";
import { CargaMasivaCancelacionComponent } from "./carga-masiva-cancelacion/carga-masiva-cancelacion.component";
import { LiquidacionAnticipadaTablaComponent } from "./liquidacion-anticipada-tabla/liquidacion-anticipada-tabla.component";
import { LiquidacionAnticipadaComponent } from "./liquidacion-anticipada/liquidacion-anticipada.component";

export const pagosRoutes: Routes = [
  { path: '', redirectTo: 'main', pathMatch: 'full' },
  { path: 'main', component: MainComponent, loadChildren: () => import('./main/main.pagos.routes').then(m => m.mainPagosRoutes) },
  { path: 'pendientes', component: ListCreditosPagosComponent },
  { path: 'bitacora', component: ListBitacoraCancelacionesComponent, },
  { path: 'bitacora/detalle/:bitacora_id', component: DetalleBitacoraComponent, },
  { path: 'abonos/:credito_id', component: AbonoComponent, },
  { path: 'masiva', loadChildren: () => import('./carga-masiva/carga.masiva.routes').then(m => m.cargaMasivaRoutes) },
  { path: 'no-identificados', component: PagosNoIdentificadosComponent },
  { path: 'facturacion', component: PagosFacturacionComponent },
  { path: 'polizas', component: PolizasComponent },  
  { path: 'carga-masiva-cancelacion', component: CargaMasivaCancelacionComponent },
  { title:'Liquidación anticipada', path: 'liquidacion-anticipada/list', component:LiquidacionAnticipadaTablaComponent },
  { title:'Liquidación anticipada', path: 'liquidacion-anticipada/nuevo', component:LiquidacionAnticipadaComponent },
  { title:'Liquidación anticipada', path: 'liquidacion-anticipada/editar/:liquidacion_id', component:LiquidacionAnticipadaComponent },
]
