import { Component, Input, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
    selector: 'app-toasty-notification',
    imports: [CommonModule],
    templateUrl: './toasty-notification.component.html',
    styleUrls: ['./toasty-notification.component.css']
})
export class ToastyNotificationComponent implements OnInit {
  @Input() title?: string = '';
  @Input() type: 'success' | 'error' | 'warning' | 'help' = 'success';
  @Input() message: string = 'Notification message';
  @Input() id!: number;
  @Input() remove!: (id: number) => void;

  icon: string = '';
  isHiding = false;

  ngOnInit(): void {
    const config = {
      success: { icon: '✔️', title: 'Éxito' },
      error: { icon: '❌', title: 'Error' },
      warning: { icon: '⚠️', title: 'Alerta' },
      help: { icon: '❓', title: 'Ayuda' },
    }[this.type];

    this.icon = config.icon;
    if (!this.title) {
      this.title = config.title;
    }

    setTimeout(() => {
      this.startExit();
    }, 5000);
  }

  startExit(): void {
    this.isHiding = true;
    setTimeout(() => {
      this.remove(this.id);
    }, 300); // match fadeOutRight duration
  }

}
