import { Component } from '@angular/core';
import { AdvancedFilter, Button, TablaComponent, TableDefinition } from "../../shared/tabla/tabla.component";
import { BitacoraCancelacionAbonoService } from '../../controllers/bitacora.cancelacion..abono.service';
import { BitacoraCancelacionAbono } from '../../models/bitacora.cancelacion.abono';
import { UtilsService } from '../../services/utils.service';

const TABLA_DEF:TableDefinition={
  style:{
    table:'table table-sm'
  },
  columns:[
    {
      key:"credito_id",
      header:'Credito'
    },
    {
      key:'row',
      header:'Nombre Cliente',
      function:(bitacora:BitacoraCancelacionAbono,utils:UtilsService)=>{
        return utils.nombreClienteFromCredito(bitacora.creditos)
      }
    },
    {
      key:'row',
      header:'Monto',
      function:(bitacora:BitacoraCancelacionAbono) =>{
        return bitacora.pagos_cargas_masivas?.importe_de_credito?? (bitacora.creditos_abonos?.monto??0).toString()
      },
      pipe:'currency'
    },
    {
      key:'pagos_cargas_masivas',
      header:'Referencia',
      subKey:'referencia_de_cliente'
    },
    "origen",
    "accion",
    "motivo",
    {
      key:'usuarios',
      header:'Hecho por:',
      keyList:['nombre','apellido_paterno']
    },
    {
      key:'created_at',
      header:'Registrado en:',
      pipe:'date'
    }
  ]
}

const VER_DETALLES_BUTTON:Button={
  style:{
    button:'btn btn-sm btn-info',
    icon:'bi bi-eye-fill'
  },
  title:'Ver detalles'
}

const ADVANCED_FILTERS:AdvancedFilter[]=[
  {
    label: 'Folio crédito:',
    key: 'creditos',
    type:'number',
    conditionals: [
      {
        key:'id',
        operator:'=',
      },
    ]
  },
  {
    label: 'Acción hecha por:',
    key: 'usuarios',
    type:'text',
    conditionals: [
      {
        key:'nombre',
        operator:'LIKE',
      },
    ]
  },
  {
    label: 'CURP Persona Física:',
    key: 'creditos.datosPersonaFisica.datosPersonales',
    type:'text',
    conditionals: [
      {
        key:'curp',
        operator:'LIKE',
      },
    ]
  },
  {
    label: 'Razon Social PM:',
    key: 'creditos.datosPersonasMorales',
    type:'text',
    conditionals: [
      {
        key:'razon_social',
        operator:'LIKE',
      },
    ]
  },
  {
    label: 'Depositado Desde:',
    key: 'pagosCargasMasivas',
    type:'date',
    conditionals: [
      {
        key:'fecha_abono',
        operator:'>=',
      },
    ]
  },
  {
    label: 'Depositado Hasta:',
    key: 'pagosCargasMasivas',
    type:'date',
    conditionals: [
      {
        key:'fecha_abono',
        operator:'<',
      },
    ]
  }
]

@Component({
    selector: 'app-list-bitacora-cancelaciones',
    imports: [
        TablaComponent,
    ],
    templateUrl: './list-bitacora-cancelaciones.component.html',
    styleUrl: './list-bitacora-cancelaciones.component.css'
})
export class ListBitacoraCancelacionesComponent {
  tablaDef=TABLA_DEF
  detalleBotton= VER_DETALLES_BUTTON
  bitacora?: BitacoraCancelacionAbono
  advancedFilters=ADVANCED_FILTERS
  showVentana:boolean=false


  constructor(
    public BitacoraController:BitacoraCancelacionAbonoService,
  ){}
}
