// #region -- table definition
const TABLE_DEF: TableDefinition = {
  style: {
    table: 'table table-sm',
  },
  columns: [
    { key: 'id', header: 'ID ABONO', style: { td: 'text-center' } },
    { key: 'creditos', subKey: 'id', header: 'Folio Crédito' },
    {
      key: 'row',
      header: 'Acreditado',
      function: function (abono: CreditoAbono, utils: UtilsService) {
        let nombre = utils.nombreClienteFromCredito(abono.creditos);
        return `${nombre}`;
      },
      styleTdFunction: () => {
        return 'fs-6';
      },
    },
    {
      key: 'row',
      header: 'Razón Social',
      function: (abono: CreditoAbono, utils: UtilsService) => {
        return utils.nombreFiscalClienteFromCredito(abono.creditos);
      },
      styleTdFunction: (abono: CreditoAbono, utils: UtilsService) => {
        const nombre = utils.nombreFiscalClienteFromCredito(abono.creditos);
        if (nombre === '' || nombre === 'N/A') {
          return 'table-danger';
        }
        let fact_detalle = abono.creditos?.facturacion_detalle;
        if (fact_detalle) {
          return utils.existeFacturaPorAbonoId(fact_detalle, abono.id)
            ? 'table-success'
            : '';
        }
        return '';
      },
    },
    {
      key: 'row',
      header: 'RFC',
      function: (abono: CreditoAbono, utils: UtilsService) => {
        return utils.rfcFromCredito(abono.creditos);
      },
      styleTdFunction: (abono: CreditoAbono, utils: UtilsService) => {
        const credito = abono.creditos;
        if (credito == null || credito == undefined) {
          return '';
        }
        // -- evaluar si el rfc es correcto
        if (!utils.validarDatosFiscales(credito, 'rfc')) {
          return 'table-danger text-center';
        }
        let fact_detalle = abono.creditos?.facturacion_detalle;
        if (fact_detalle) {
          return utils.existeFacturaPorAbonoId(fact_detalle, abono.id)
            ? 'table-success'
            : '';
        }
        return '';
      },
      style: { th: 'text-center' },
    },
    {
      key: 'row',
      header: 'Regimen',
      function: (abono: CreditoAbono, utils: UtilsService) => {
        return utils.getRegimenFiscalCodeFromCredito(abono.creditos);
      },
      styleTdFunction: (abono: CreditoAbono, utils: UtilsService) => {
        const credito = abono.creditos;
        if (credito == null || credito == undefined) {
          return '';
        }
        // -- evaluar si el rfc es correcto
        if (!utils.validarDatosFiscales(credito, 'regimen')) {
          return 'table-danger text-center';
        }
        return '';
      },
    },
    {
      key: 'row',
      header: 'Código Postal',
      function: (abono: CreditoAbono, utils: UtilsService) => {
        let cp = utils.getCpFiscal(abono.creditos);
        return cp.toString().padStart(5, '0');
      },
      styleTdFunction: (abono: CreditoAbono, utils: UtilsService) => {
        const credito = abono.creditos;
        if (credito == null || credito == undefined) {
          return '';
        }
        // -- evaluar si el rfc es correcto
        if (!utils.validarDatosFiscales(credito, 'cp')) {
          return 'table-danger text-center';
        }
        return '';
      },
      style: { th: 'text-center' },
    },
    {
      key: 'fecha',
      header: 'FECHA ABONO',
      style: { td: 'text-center' },
      pipe: 'date',
    },
    {
      key: 'row',
      header: 'CAPITAL',
      function: (abono: CreditoAbono) => {
        const estadoCuenta = abono.creditos?.estado_cuenta;
        const abonosDistribuidos: AbonoDistribuido[] = JSON.parse(
          estadoCuenta?.abonos_distribuidos as any,
        );
        if (abonosDistribuidos == null || abonosDistribuidos == undefined) {
          return '0';
        }
        const pagoCapital =
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)
            ?.pago_capital || 0;
        return `${pagoCapital}`;
      },
      pipe: 'currency',
      style: { td: 'text-end' },
    },
    // -- Pago Interés
    {
      key: 'row',
      header: 'Interés',
      function: (abono: CreditoAbono) => {
        const estadoCuenta = abono.creditos?.estado_cuenta;
        const abonosDistribuidos: AbonoDistribuido[] = JSON.parse(
          estadoCuenta?.abonos_distribuidos as any,
        );
        if (abonosDistribuidos == null || abonosDistribuidos == undefined) {
          return '0';
        }
        const pagoInteres =
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)
            ?.pago_interes || 0;

        return `${pagoInteres}`;
      },
      styleTdFunction: (abono: CreditoAbono) => {
        let pagoInteres = 0;

        const estadoCuenta = abono.creditos?.estado_cuenta;
        const abonosDistribuidos: AbonoDistribuido[] = JSON.parse(
          estadoCuenta?.abonos_distribuidos as any,
        );
        if (abonosDistribuidos) {
          pagoInteres =
            abonosDistribuidos.find((ab) => ab.abono.id == abono.id)
              ?.pago_interes || 0;
        }
        return pagoInteres == 0 ? 'table-danger' : '';
      },
      pipe: 'currency',
      style: { td: 'text-end', th: 'text-center' },
    },
    // -- ./Pago Interés
    {
      key: 'row',
      header: 'IVA',
      function: (abono: CreditoAbono) => {
        const estadoCuenta = abono.creditos?.estado_cuenta;
        const abonosDistribuidos: AbonoDistribuido[] = JSON.parse(
          estadoCuenta?.abonos_distribuidos as any,
        );
        if (abonosDistribuidos == null || abonosDistribuidos == undefined) {
          return '0';
        }
        const pagoIva =
          abonosDistribuidos.find((ab) => ab.abono.id == abono.id)?.pago_iva ||
          0;
        return `${pagoIva}`;
      },
      pipe: 'currency',
      style: { td: 'text-end', th: 'text-center' },
    },
    {
      key: 'monto',
      header: 'MONTO ABONO',
      pipe: 'currency',
      style: { td: 'text-end', th: 'text-center' },
    },
  ],
};
